package main

import (
	"errors"
	"testing"
)

var errBoom = errors.New("boom")

func boom() (string, error) {
	return "", errBoom
}

func TestTripsOpenAfterConsecutiveFailures(t *testing.T) {
	b := NewCircuitBreaker(3, 10)
	for i := 0; i < 3; i++ {
		if _, err := b.Call(boom, 0); err != errBoom {
			t.Fatalf("expected errBoom, got %v", err)
		}
	}
	if _, err := b.Call(func() (string, error) { return "should not run", nil }, 0); err != ErrCircuitOpen {
		t.Fatalf("expected ErrCircuitOpen, got %v", err)
	}
}

func TestFailsFastWithoutCallingFnWhileOpen(t *testing.T) {
	b := NewCircuitBreaker(1, 100)
	b.Call(boom, 0)
	called := false
	_, err := b.Call(func() (string, error) { called = true; return "x", nil }, 1)
	if err != ErrCircuitOpen {
		t.Fatalf("expected ErrCircuitOpen, got %v", err)
	}
	if called {
		t.Fatalf("fn must not be called while open")
	}
}

func TestHalfOpenTrialAfterTimeoutSuccessCloses(t *testing.T) {
	b := NewCircuitBreaker(1, 10)
	b.Call(boom, 0)
	if v, err := b.Call(func() (string, error) { return "ok", nil }, 10); err != nil || v != "ok" {
		t.Fatalf("expected ok, got %v %v", v, err)
	}
	if v, err := b.Call(func() (string, error) { return "still-fine", nil }, 11); err != nil || v != "still-fine" {
		t.Fatalf("expected still-fine, got %v %v", v, err)
	}
}

func TestHalfOpenFailureReopensAndResetsClock(t *testing.T) {
	b := NewCircuitBreaker(1, 10)
	b.Call(boom, 0)
	if _, err := b.Call(boom, 10); err != errBoom {
		t.Fatalf("expected errBoom at half-open trial, got %v", err)
	}
	if _, err := b.Call(func() (string, error) { return "too soon", nil }, 15); err != ErrCircuitOpen {
		t.Fatalf("expected ErrCircuitOpen at t=15, got %v", err)
	}
	if v, err := b.Call(func() (string, error) { return "ok now", nil }, 20); err != nil || v != "ok now" {
		t.Fatalf("expected ok now at t=20, got %v %v", v, err)
	}
}

