package main

import "errors"

var ErrCircuitOpen = errors.New("circuit open")

type state int

const (
	closed state = iota
	open
	halfOpen
)

type CircuitBreaker struct {
	FailureThreshold int
	ResetTimeout     int64
	state            state
	failures         int
	openedAt         int64
}

func NewCircuitBreaker(failureThreshold int, resetTimeout int64) *CircuitBreaker {
	return &CircuitBreaker{FailureThreshold: failureThreshold, ResetTimeout: resetTimeout, state: closed}
}

func (b *CircuitBreaker) Call(fn func() (string, error), now int64) (string, error) {
	if b.state == open {
		if now-b.openedAt < b.ResetTimeout {
			return "", ErrCircuitOpen
		}
		b.state = halfOpen
	}

	result, err := fn()
	if err != nil {
		if b.state == halfOpen {
			b.state = open
			b.openedAt = now
		} else {
			b.failures++
			if b.failures >= b.FailureThreshold {
				b.state = open
				b.openedAt = now
			}
		}
		return "", err
	}

	b.state = closed
	b.failures = 0
	return result, nil
}

